    amount numeric(20,4),
    currency character(3),
    amount_ngn numeric(20,2),
    amount_usd numeric(20,4),
    fx_rate numeric(20,8),
    fx_source character varying(20),
    status character varying(50),
    transaction_type character varying(50),
    payment_source character varying(50),
    ingestion_mode character varying(20),
    virtual_account_type character varying(20),
    settlement_mode character varying(20),
    expected_settlement_at timestamp with time zone,
    partner_id character varying(100),
    dealer_id character varying(100),
    product_type character varying(50),
    gross_revenue numeric(20,2),
    commission_amount numeric(20,2),
    commission_rate numeric(8,6),
    settlement_period character varying(6),
    linked_statement_ref character varying(150),
    sender_name character varying(200),
    sender_phone character varying(30),
    sender_email character varying(200),
    receiver_name character varying(200),
