    completed_at timestamp with time zone,
    normalized_at timestamp with time zone DEFAULT now(),
    metadata jsonb
);


--
-- Name: partner_settlements; Type: VIEW; Schema: normalized; Owner: -
--

CREATE VIEW normalized.partner_settlements AS
 WITH sales_agg AS (
         SELECT transactions.dealer_id,
            transactions.settlement_period,
            count(*) AS sale_count,
            sum(transactions.amount_ngn) AS total_sales_ngn
           FROM normalized.transactions
          WHERE (((transactions.event_type)::text = 'telecom.dealer_sale'::text) AND (transactions.dealer_id IS NOT NULL) AND (transactions.settlement_period IS NOT NULL))
          GROUP BY transactions.dealer_id, transactions.settlement_period
        ), statements_agg AS (
         SELECT transactions.dealer_id,
            transactions.settlement_period,
            count(*) AS statement_count,
            sum(transactions.commission_amount) AS expected_commission_ngn,
            sum(transactions.gross_revenue) AS statement_gross_revenue_ngn
           FROM normalized.transactions
          WHERE (((transactions.event_type)::text = 'telecom.commission_statement'::text) AND (transactions.dealer_id IS NOT NULL) AND (transactions.settlement_period IS NOT NULL))
          GROUP BY transactions.dealer_id, transactions.settlement_period
        ), settlements_agg AS (
         SELECT transactions.dealer_id,
            transactions.settlement_period,
            count(*) AS settlement_count,
            sum(transactions.amount_ngn) AS total_settled_ngn,
            count(*) FILTER (WHERE ((transactions.status)::text = 'SUCCESS'::text)) AS paid_count,
            count(*) FILTER (WHERE ((transactions.status)::text = 'PENDING'::text)) AS partial_count,
            count(*) FILTER (WHERE ((transactions.status)::text = 'FAILED'::text)) AS disputed_count
           FROM normalized.transactions
          WHERE (((transactions.event_type)::text = 'telecom.settlement'::text) AND (transactions.dealer_id IS NOT NULL) AND (transactions.settlement_period IS NOT NULL))
          GROUP BY transactions.dealer_id, transactions.settlement_period
        )
 SELECT dealer_id,
    settlement_period,
    sales_agg.sale_count,
    sales_agg.total_sales_ngn,
    statements_agg.statement_count,
    statements_agg.expected_commission_ngn,
    statements_agg.statement_gross_revenue_ngn,
    settlements_agg.settlement_count,
    settlements_agg.total_settled_ngn,
    settlements_agg.paid_count,
    settlements_agg.partial_count,
    settlements_agg.disputed_count,
    (COALESCE(settlements_agg.total_settled_ngn, (0)::numeric) - COALESCE(statements_agg.expected_commission_ngn, (0)::numeric)) AS payment_variance_ngn,
        CASE
            WHEN ((statements_agg.expected_commission_ngn IS NULL) AND (COALESCE(sales_agg.sale_count, (0)::bigint) > 0)) THEN 'SALES_WITHOUT_STATEMENT'::text
            WHEN ((settlements_agg.total_settled_ngn IS NULL) AND (statements_agg.expected_commission_ngn IS NOT NULL)) THEN 'STATEMENT_WITHOUT_PAYMENT'::text
            WHEN (COALESCE(settlements_agg.disputed_count, (0)::bigint) > 0) THEN 'DISPUTED'::text
            WHEN (COALESCE(settlements_agg.partial_count, (0)::bigint) > 0) THEN 'PARTIALLY_PAID'::text
            WHEN (abs((COALESCE(settlements_agg.total_settled_ngn, (0)::numeric) - COALESCE(statements_agg.expected_commission_ngn, (0)::numeric))) > 0.01) THEN 'AMOUNT_MISMATCH'::text
            ELSE 'RECONCILED'::text
        END AS reconciliation_status
   FROM ((sales_agg
     FULL JOIN statements_agg USING (dealer_id, settlement_period))
     FULL JOIN settlements_agg USING (dealer_id, settlement_period));


--
-- Name: VIEW partner_settlements; Type: COMMENT; Schema: normalized; Owner: -
--

COMMENT ON VIEW normalized.partner_settlements IS 'v1.3.0 — per-dealer per-period reconciliation surface. Unions telecom.dealer_sale + telecom.commission_statement + telecom.settlement events. Consumed by the FBB Revenue Intelligence platform.';


